"""Deutsch — Koran (quran_001 … quran_080)."""

T = {
"quran_001": ("Wie heißt das erste Kapitel (Sure) des Korans?", ["Al-Fatiha", "Al-Baqara", "Al-Ikhlas", "An-Nas"], "Al-Fatiha, „die Eröffnende“, ist das erste Kapitel des Korans."),
"quran_002": ("Wie viele Kapitel (Suren) hat der Koran?", ["114", "99", "100", "120"], "Der Koran besteht aus 114 Suren."),
"quran_003": ("Welche ist die längste Sure des Korans?", ["Al-Baqara", "Al-Fatiha", "Al-Kawthar", "Al-Asr"], "Al-Baqara ist mit 286 Versen die längste Sure des Korans."),
"quran_004": ("Welche ist die kürzeste Sure des Korans?", ["Al-Kawthar", "Al-Ikhlas", "Al-Asr", "An-Nasr"], "Al-Kawthar ist mit 3 Versen die kürzeste Sure des Korans."),
"quran_005": ("In welcher Sprache wurde der Koran offenbart?", ["Arabisch", "Aramäisch", "Hebräisch", "Persisch"], "Der Koran sagt ausdrücklich, dass er in arabischer Sprache offenbart wurde."),
"quran_006": ("Wie heißt die 19. Sure, benannt nach der Mutter Isas?", ["Maryam", "Yusuf", "Al-Kahf", "Ta-Ha"], "Die 19. Sure des Korans heißt Maryam, nach der Mutter des Propheten Isa."),
"quran_007": ("Wie nennt man ein Kapitel des Korans?", ["Eine Sure", "Einen Hadith", "Einen Juz'", "Einen Tafsir"], "Der Koran ist in Kapitel unterteilt, die Suren heißen."),
"quran_008": ("Wie nennt man einen Vers des Korans?", ["Eine Aya", "Eine Sure", "Einen Hadith", "Einen Ruku'"], "Jeder Vers des Korans heißt Aya, was „Zeichen“ bedeutet."),
"quran_009": ("Welche Sure wird in jeder Gebetseinheit (Rak'a) verpflichtend rezitiert?", ["Al-Fatiha", "Al-Ikhlas", "Al-Kawthar", "Al-Fil"], "Das Rezitieren von Al-Fatiha ist laut einem authentischen Hadith eine Säule des Gebets."),
"quran_010": ("Wem wurde der Koran offenbart?", ["Dem Propheten Muhammad ﷺ", "Dem Propheten Musa", "Dem Propheten Isa", "Dem Propheten Dawud"], "Der Koran wurde dem Propheten Muhammad ﷺ durch den Engel Jibril offenbart."),
"quran_011": ("Wie heißt der berühmte Vers 255 der Sure Al-Baqara?", ["Ayat al-Kursi (der Thronvers)", "Ayat an-Nur", "Ayat as-Siyam", "Ayat ad-Dayn"], "Vers 2:255, Ayat al-Kursi, beschreibt Allahs Größe: „Allah, es gibt keinen Gott außer Ihm, dem Lebendigen…“"),
"quran_012": ("Welche Sure beginnt nicht mit „Bismillah ir-Rahman ir-Rahim“?", ["At-Tawba", "Al-Fatiha", "Ya-Sin", "Al-Kahf"], "At-Tawba (Sure 9) ist die einzige Sure, die nicht mit der Basmala beginnt."),
"quran_013": ("Wovon handelt der längste Vers des Korans (2:282)?", ["Vom schriftlichen Festhalten von Schulden", "Von der Pilgerfahrt", "Vom Fasten", "Vom Erbe"], "Der längste Vers des Korans lehrt, Schulden aufzuschreiben und Zeugen zu nehmen: Ehrlichkeit wird geschützt."),
"quran_014": ("Mit welchem Wort beginnen die allerersten offenbarten Verse des Korans?", ["Iqra' (Lies!)", "Qul (Sprich!)", "Sabbih (Preise!)", "Kutiba (Es wurde vorgeschrieben)"], "Die ersten offenbarten Verse beginnen mit „Iqra'“: „Lies, im Namen deines Herrn, der erschuf.“"),
"quran_015": ("Besser als wie viele Monate ist laut Koran die Nacht Al-Qadr?", ["Tausend Monate", "Hundert Monate", "Zwölf Monate", "Vierzig Monate"], "„Die Nacht Al-Qadr ist besser als tausend Monate“: Eine Nacht im Ramadan ist mehr wert als ein Leben voller Gottesdienst."),
"quran_016": ("Wie heißen die beiden letzten Suren, Al-Falaq und An-Nas, die zum Schutz rezitiert werden?", ["Al-Mu'awwidhatan (die beiden Schutzsuren)", "Az-Zahrawan", "Al-Mufassal", "As-Sab' at-Tiwal"], "Al-Falaq und An-Nas heißen „al-Mu'awwidhatan“: Sie werden rezitiert, um Allahs Schutz zu suchen."),
"quran_017": ("In wie viele Teile (Juz') wird der Koran traditionell eingeteilt?", ["30", "10", "60", "114"], "Der Koran ist in 30 Juz' eingeteilt, was hilft, ihn in einem Monat zu vollenden, etwa im Ramadan."),
"quran_018": ("Wie viele Verse hat die Sure Al-Fatiha?", ["7", "3", "10", "14"], "Al-Fatiha hat sieben Verse, die in jeder Gebetseinheit rezitiert werden."),
"quran_019": ("Welche Sure ist nach einem Metall benannt?", ["Al-Hadid (Das Eisen)", "An-Nur (Das Licht)", "Ar-Ra'd (Der Donner)", "Ad-Dukhan (Der Rauch)"], "Sure 57 heißt Al-Hadid: „Wir sandten das Eisen herab, in dem große Kraft und Nutzen für die Menschen liegt.“"),
"quran_020": ("Welche Geschichte nennt der Koran „die schönste der Geschichten“?", ["Die Geschichte Yusufs", "Die Geschichte Nuhs", "Die Geschichte der Leute der Höhle", "Die Geschichte des Elefanten"], "„Wir erzählen dir die schönste der Geschichten“: So beginnt die Geschichte Yusufs."),
"quran_021": ("Wie viele Verse hat Al-Baqara, die längste Sure?", ["286", "114", "200", "365"], "Al-Baqara hat 286 Verse: die längste Sure des Korans."),
"quran_022": ("Welche kurze Sure verkündet: „Sprich: Er ist Allah, ein Einziger“?", ["Al-Ikhlas", "Al-Falaq", "An-Nas", "Al-Kawthar"], "Al-Ikhlas verkündet in vier Versen die vollkommene Einheit Allahs."),
"quran_023": ("Über ungefähr wie viele Jahre wurde der Koran offenbart?", ["23 Jahre", "1 Jahr", "10 Jahre", "40 Jahre"], "Der Koran wurde über etwa 23 Jahre schrittweise offenbart, in Mekka und dann in Medina."),
"quran_024": ("Welches war laut Koran das erste Haus, das für die Menschen zur Anbetung Allahs errichtet wurde?", ["Die Ka'ba in Bakka (Mekka)", "Die Moschee von Quba", "Bayt al-Maqdis", "Die Moschee des Propheten ﷺ"], "„Das erste Haus, das für die Menschen errichtet wurde, ist das in Bakka, gesegnet…“: die Ka'ba in Mekka."),
"quran_025": ("Welche Sure ist nach dem Elefanten benannt?", ["Al-Fil", "An-Nahl", "An-Naml", "Al-Baqara"], "Sure 105, Al-Fil („Der Elefant“), erinnert an Abrahas Elefantenheer, das vor Mekka aufgehalten wurde."),
"quran_026": ("Nach welchem Insekt ist die Sure An-Nahl benannt?", ["Der Biene", "Der Ameise", "Der Spinne", "Der Fliege"], "An-Nahl bedeutet „die Bienen“; darin gibt Allah der Biene ein, ihre Behausungen zu bauen (16:68)."),
"quran_027": ("Welche Sure ist nach der Ameise benannt?", ["An-Naml", "An-Nahl", "Al-Ankabut", "Al-An'am"], "An-Naml („Die Ameisen“, Sure 27) erzählt von der Ameise, die ihre Artgenossen warnte, als Sulaymans Heer nahte."),
"quran_028": ("Womit vergleicht der Koran in der Sure Al-Ankabut diejenigen, die sich Beschützer außer Allah nehmen?", ["Mit der Spinne, die sich ein brüchiges Haus baut", "Mit der Biene, die ihren Stock baut", "Mit der Ameise, die Vorräte sammelt", "Mit dem hechelnden Hund"], "„Das schwächste der Häuser ist das Haus der Spinne“ (29:41), daher der Name der Sure."),
"quran_029": ("Nach welchem Tier ist die Sure Al-Baqara benannt?", ["Der Kuh", "Dem Kamel", "Dem Pferd", "Dem Schaf"], "Al-Baqara („Die Kuh“) erinnert an die Kuh, die die Kinder Israels opfern sollten (2:67)."),
"quran_030": ("Was bedeutet der Titel der Sure 6, Al-An'am?", ["Das Vieh", "Die Vögel", "Die Gärten", "Die Sterne"], "Al-An'am bedeutet „das Vieh“; die Sure widerlegt die von den Heiden erfundenen Regeln über das Vieh."),
"quran_031": ("Welcher Vers wird in der Sure Ar-Rahman viele Male wiederholt?", ["„Welche der Wohltaten eures Herrn wollt ihr leugnen?“", "„Allah ist der Größte“", "„Sprich: Er ist Allah, ein Einziger“", "„Lob sei Allah“"], "Dieser Refrain („Fa-bi-ayyi ala'i rabbikuma tukadhdhiban“) kehrt in Sure 55 31-mal wieder."),
"quran_032": ("Wie lange schliefen die Leute der Höhle laut Sure Al-Kahf?", ["Dreihundert Jahre und neun dazu", "Hundert Jahre", "Vierzig Jahre", "Tausend Jahre"], "„Sie blieben in ihrer Höhle dreihundert Jahre und fügten neun hinzu“ (18:25)."),
"quran_033": ("Welches Tier war bei den Leuten der Höhle?", ["Ein Hund", "Eine Katze", "Ein Esel", "Eine Ziege"], "„Ihr Hund streckte seine Vorderpfoten am Eingang aus“ (18:18)."),
"quran_034": ("Gegen welche Völker baute Dhul-Qarnayn laut Al-Kahf einen Wall?", ["Ya'juj und Ma'juj (Gog und Magog)", "'Ad und Thamud", "Die Römer", "Die Perser"], "Ein Volk bat ihn um Schutz vor Ya'juj und Ma'juj; er errichtete einen Wall aus Eisen und Kupfer (18:94-96)."),
"quran_035": ("Welcher Vers beginnt mit „Allah ist das Licht der Himmel und der Erde“?", ["Der Lichtvers (An-Nur 24:35)", "Der Thronvers", "Der Schuldenvers", "Der Höhlenvers"], "„Ayat an-Nur“ vergleicht Sein Licht mit einer Nische, in der eine Lampe leuchtet (24:35)."),
"quran_036": ("Welche Sure entspricht laut einem Hadith bei al-Buchari einem Drittel des Korans?", ["Al-Ikhlas", "Al-Fatiha", "Ya-Sin", "Al-Kahf"], "Der Prophet ﷺ sagte über „Qul huwa Allahu ahad“, sie „entspreche einem Drittel des Korans“."),
"quran_037": ("Welchen Vers nannte der Prophet ﷺ laut Sahih Muslim den größten des Korans?", ["Den Thronvers (Ayat al-Kursi)", "Den ersten Vers von Al-Fatiha", "Den letzten Vers von Al-Baqara", "Den Lichtvers"], "Er fragte Ubayy ibn Ka'b, welcher Vers der größte sei; Ubayy antwortete Ayat al-Kursi, und der Prophet ﷺ beglückwünschte ihn."),
"quran_038": ("Welcher Feind des Propheten ﷺ wird in der Sure Al-Masad genannt?", ["Abu Lahab", "Abu Jahl", "Abu Sufyan", "Al-Walid"], "„Zugrunde gehen sollen die Hände Abu Lahabs“ (111:1): Dieser Onkel des Propheten ﷺ bekämpfte ihn offen."),
"quran_039": ("Wie endet die Sure Al-Kafirun?", ["„Euch eure Religion, und mir meine Religion“", "„Allah ist der Größte“", "„Und niemand ist Ihm gleich“", "„Vor dem Übel des Neiders“"], "„Lakum dinukum wa liya din“ (109:6) bekräftigt die klare Trennung zwischen Islam und Götzendienst."),
"quran_040": ("Wovon handelt die Sure An-Nasr?", ["Von Allahs Hilfe und den Menschen, die in Scharen in die Religion eintreten", "Von der Erschaffung des Himmels", "Vom Fasten im Ramadan", "Von der Geschichte Yusufs"], "„Wenn Allahs Hilfe und der Sieg kommen und du die Menschen in Scharen in Allahs Religion eintreten siehst“ (110:1-2)."),
"quran_041": ("Wer entgeht laut Sure Al-Asr dem Verlust?", ["Die glauben, Gutes tun und einander die Wahrheit und die Geduld ans Herz legen", "Die Reichen", "Die Starken", "Die Reisenden"], "„Der Mensch ist im Verlust, außer denen, die glauben, gute Werke tun und einander die Wahrheit und die Geduld ans Herz legen“ (103:2-3)."),
"quran_042": ("Was tut in der Sure Al-Ma'un „derjenige, der das Gericht leugnet“?", ["Er stößt die Waise zurück und ermahnt nicht zur Speisung des Armen", "Er zerstört Moscheen", "Er weigert sich zu reisen", "Er lügt über sein Vermögen"], "„Das ist derjenige, der die Waise zurückstößt und nicht zur Speisung des Armen ermahnt“ (107:2-3)."),
"quran_043": ("Woraus erschuf Allah den Menschen laut den ersten offenbarten Versen (Al-Alaq)?", ["Aus einem Anhängsel (Alaq)", "Aus Licht", "Aus Feuer", "Aus Wind"], "„Lies, im Namen deines Herrn, der erschuf, der den Menschen aus einem Anhängsel erschuf“ (96:1-2)."),
"quran_044": ("Worauf bezieht sich der koranische Ausdruck „die sieben oft wiederholten Verse“ (as-Sab' al-Mathani)?", ["Auf Al-Fatiha", "Auf die sieben längsten Suren", "Auf Ayat al-Kursi", "Auf die letzten sieben Verse des Korans"], "„Wir haben dir sieben der oft wiederholten und den gewaltigen Koran gegeben“ (15:87): Al-Fatiha, in jeder Rak'a rezitiert."),
"quran_045": ("Was bedeutet „Al-Furqan“, einer der Namen des Korans?", ["Die Unterscheidung (zwischen Wahrheit und Falschheit)", "Das Licht", "Die Ermahnung", "Die Heilung"], "„Gesegnet sei Der, der den Furqan auf Seinen Diener herabsandte“ (25:1): das Buch, das Wahrheit von Falschheit trennt."),
"quran_046": ("Wobei schwört Allah zu Beginn der Sure At-Tur?", ["Beim Berg (Tur)", "Bei der Sonne", "Beim Feigenbaum", "Bei der Nacht"], "„Beim Berg! Und bei einem geschriebenen Buch…“ (52:1-2): Der Tur ist der Berg, auf dem Musa die Offenbarung empfing."),
"quran_047": ("Was bedeutet „An-Najm“, der Titel der Sure 53?", ["Der Stern", "Der Mond", "Die Sonne", "Die Morgendämmerung"], "„Beim Stern, wenn er sinkt!“ (53:1)."),
"quran_048": ("Wer steigt laut Sure Al-Qadr in der Nacht der Bestimmung herab?", ["Die Engel und der Geist (Jibril)", "Die Propheten", "Die Dschinn", "Die Winde"], "„Die Engel und der Geist steigen in ihr mit der Erlaubnis ihres Herrn herab“ (97:4)."),
"quran_049": ("Was ist der Koran laut Koran für die Gläubigen?", ["Heilung und Barmherzigkeit", "Nur ein Gedicht", "Ein Geschichtsbuch", "Ein Kalender"], "„Wir senden vom Koran herab, was Heilung und Barmherzigkeit für die Gläubigen ist“ (17:82)."),
"quran_050": ("Welche Herausforderung stellt der Koran denen, die an seinem göttlichen Ursprung zweifeln?", ["Eine einzige Sure gleicher Art hervorzubringen", "Den ganzen Koran auswendig zu rezitieren", "Den Koran zu übersetzen", "Eine Moschee zu bauen"], "„Wenn ihr im Zweifel seid über das, was Wir herabgesandt haben, dann bringt eine Sure gleicher Art hervor“ (2:23)."),
"quran_051": ("Welche Sure wird „Umm al-Qur'an“ (die Mutter des Korans) genannt?", ["Al-Fatiha", "Al-Baqara", "Ya-Sin", "Al-Ikhlas"], "Der Prophet ﷺ sagte: „Umm al-Qur'an sind die sieben oft wiederholten Verse und der gewaltige Koran.“"),
"quran_052": ("Was ist eine „mekkanische“ Sure (Makkiyya)?", ["Eine vor der Hidschra offenbarte Sure", "Eine in Medina offenbarte Sure", "Eine Sure über die Ka'ba", "Eine sehr kurze Sure"], "Die Gelehrten ordnen die Suren nach der Zeit: vor der Auswanderung nach Medina (mekkanisch) oder danach (medinensisch)."),
"quran_053": ("Wie viele Suren beginnen mit den Buchstaben „Alif, Lam, Mim“?", ["Sechs", "Zwei", "Zehn", "Eine"], "Al-Baqara, Al Imran, Al-Ankabut, Ar-Rum, Luqman und As-Sajda beginnen mit „Alif, Lam, Mim“."),
"quran_054": ("Wie heißen die einzelnen Buchstaben, mit denen manche Suren beginnen (Alif Lam Mim, Ya Sin, Qaf…)?", ["Die abgetrennten Buchstaben (al-Huruf al-Muqatta'a)", "Die aufgehobenen Verse", "Die Sonnenbuchstaben", "Die Tajwid-Buchstaben"], "Neunundzwanzig Suren beginnen mit diesen Buchstaben, deren volle Bedeutung allein Allah kennt."),
"quran_055": ("Welche Sure ist nach dem Propheten Muhammad ﷺ benannt?", ["Sure 47, Muhammad", "Sure 1, Al-Fatiha", "Sure 36, Ya-Sin", "Sure 112, Al-Ikhlas"], "Sure 47 heißt „Muhammad“; sie nennt seinen Namen in Vers 2."),
"quran_056": ("Was ist der erste Rat Luqmans an seinen Sohn, der im Koran zitiert wird?", ["Allah nichts beizugesellen", "Die Sterne zu studieren", "Kaufmann zu werden", "Weit zu reisen"], "„O mein Sohn, geselle Allah nichts bei; wahrlich, Beigesellung ist ein gewaltiges Unrecht“ (31:13)."),
"quran_057": ("Unter welchem anderen Namen ist die Sure At-Tawba bekannt?", ["Bara'a (die Lossagung)", "An-Nur", "Al-Anfal", "Al-Fath"], "Ihr erstes Wort ist „Bara'a“: eine Lossagung Allahs und Seines Gesandten von den Götzendienern (9:1)."),
"quran_058": ("Welche Sure beginnt mit den beiden Buchstaben „Ya, Sin“?", ["Ya-Sin (Sure 36)", "Ta-Ha", "Qaf", "Sad"], "Sure 36 beginnt mit „Ya-Sin. Beim weisen Koran!“"),
"quran_059": ("Was bedeutet „Al-Mulk“, der Titel der Sure 67?", ["Die Herrschaft / das Königreich", "Das Licht", "Die Reise", "Der Sieg"], "„Gesegnet sei Der, in Dessen Hand die Herrschaft (al-Mulk) ist“ (67:1)."),
"quran_060": ("Welche ist die letzte Sure des Korans?", ["An-Nas", "Al-Falaq", "Al-Ikhlas", "Al-Fatiha"], "An-Nas („Die Menschen“), Sure 114, schließt den Koran ab: „Sprich: Ich suche Zuflucht beim Herrn der Menschen.“"),
"quran_061": ("Wie beginnt die Sure Al-Falaq?", ["„Sprich: Ich suche Zuflucht beim Herrn des Morgengrauens“", "„Sprich: Er ist Allah, ein Einziger“", "„Bei der Zeit!“", "„Lob sei Allah“"], "„Qul a'udhu bi-rabbi-l-falaq“ (113:1): Al-Falaq bedeutet das Morgengrauen."),
"quran_062": ("Welche zwei Hügel nennt der Koran unter den „Zeichen Allahs“?", ["As-Safa und Al-Marwa", "Uhud und Thawr", "Arafat und Mina", "Hira und Abu Qubays"], "„As-Safa und Al-Marwa gehören zu den Zeichen Allahs“ (2:158): Zwischen ihnen wird der Sa'y der Pilgerfahrt gelaufen."),
"quran_063": ("Wer ist die einzige Frau, die im Koran namentlich genannt wird?", ["Maryam", "Khadija", "Asiya", "Hajar"], "Maryam, die Mutter Isas, wird in mehreren Suren genannt, und eine ganze Sure trägt ihren Namen."),
"quran_064": ("Wer ist der einzige Gefährte des Propheten ﷺ, der im Koran namentlich genannt wird?", ["Zayd ibn Haritha", "Abu Bakr", "Umar", "Ali"], "„Als Zayd seine Beziehung zu ihr beendet hatte…“ (33:37): Zayd, der Freigelassene des Propheten ﷺ, ist der einzige genannte Gefährte."),
"quran_065": ("Wer waren Harut und Marut, die in der Sure Al-Baqara erwähnt werden?", ["Zwei nach Babylon gesandte Engel", "Zwei Propheten", "Zwei Könige Ägyptens", "Zwei Gefährten"], "„…was auf die beiden Engel Harut und Marut in Babylon herabgesandt wurde“ (2:102): Sie warnten, dass Zauberei eine Prüfung sei."),
"quran_066": ("Wer ist laut Koran der Edelste vor Allah?", ["Der Gottesfürchtigste", "Der Reichste", "Der Stärkste", "Der Berühmteste"], "„Der Edelste von euch vor Allah ist der Gottesfürchtigste“ (49:13)."),
"quran_067": ("Worauf bezieht sich „Al-Waqi'a“, der Titel der Sure 56?", ["Auf das unausweichliche Ereignis (den Tag der Auferstehung)", "Auf die Karawane", "Auf die Ameise", "Auf die Nachtreise"], "„Wenn das Ereignis eintrifft…“ (56:1): Die Sure beschreibt die drei Gruppen des Jüngsten Tages."),
"quran_068": ("Bei welchem Gegenstand schwört Allah zu Beginn der Sure Al-Qalam?", ["Beim Schreibrohr", "Beim Schwert", "Bei der Waage", "Bei der Lampe"], "„Nun. Beim Schreibrohr und dem, was sie schreiben!“ (68:1)."),
"quran_069": ("Wie beginnt die Sure Al-Fajr?", ["Mit einem Schwur bei der Morgendämmerung und zehn Nächten", "Mit einem Schwur beim Feigenbaum", "Mit einer Geschichte Yusufs", "Nur mit der Basmala"], "„Bei der Morgendämmerung! Und bei den zehn Nächten!“ (89:1-2)."),
"quran_070": ("Bei welchem Himmelskörper schwört Allah zu Beginn der Sure Ash-Shams?", ["Bei der Sonne", "Nur beim Mond", "Bei den Sternen", "Bei den Planeten"], "„Bei der Sonne und ihrem Glanz!“ (91:1); Ash-Shams bedeutet „die Sonne“."),
"quran_071": ("Welche Sure beginnt mit: „Ist über den Menschen eine Zeitspanne vergangen, in der er nichts Nennenswertes war?“", ["Al-Insan (Sure 76)", "Al-Kahf", "Al-Hajj", "Al-Fatiha"], "Al-Insan („Der Mensch“), auch Ad-Dahr genannt, erinnert daran, dass der Mensch vor seiner Erschaffung nichts war (76:1)."),
"quran_072": ("Wofür hat Allah den Koran laut Koran leicht gemacht?", ["Zum Gedenken und Auswendiglernen", "Für den Handel", "Für die Übersetzung", "Zum Vergessen"], "„Wir haben den Koran leicht zum Gedenken gemacht; gibt es jemanden, der sich ermahnen lässt?“ (54:17), viermal in der Sure wiederholt."),
"quran_073": ("Welches Zeichen erwähnt die Sure Al-Qamar gleich in ihrem ersten Vers?", ["Der Mond spaltete sich", "Die Sonne erlosch", "Das Meer öffnete sich", "Der Berg sprach"], "„Die Stunde ist nahe, und der Mond hat sich gespalten“ (54:1): ein Zeichen, das den Mekkanern gezeigt wurde."),
"quran_074": ("Warum wurde der Koran laut Koran schrittweise statt auf einmal offenbart?", ["Um das Herz des Propheten ﷺ zu festigen", "Weil er zu lang war", "Um ihn vor Feinden zu verbergen", "Wegen der Reisen"], "„So, damit Wir dein Herz damit festigen, und Wir haben ihn in klarer Vortragsweise vorgetragen“ (25:32)."),
"quran_075": ("Welche Suren rezitierte der Prophet ﷺ laut Aisha jede Nacht vor dem Schlafen in seine Hände?", ["Al-Ikhlas, Al-Falaq und An-Nas", "Al-Fatiha und Al-Baqara", "Ya-Sin und Al-Mulk", "Al-Kahf und Maryam"], "Er blies in seine Hände und rezitierte die drei „Qul“-Suren, dann strich er damit über seinen Körper, dreimal."),
"quran_076": ("Wie heißt die Niederwerfung, die beim Rezitieren bestimmter Koranverse vollzogen wird?", ["Die Rezitationsniederwerfung (Sujud at-Tilawa)", "Die Niederwerfung der Vergesslichkeit", "Die Dankesniederwerfung", "Der Ruku'"], "Der Koran enthält Niederwerfungsverse, wie den letzten Vers von Al-Alaq: „Wirf dich nieder und nähere dich“ (96:19)."),
"quran_077": ("Wie heißt die Wissenschaft von den Regeln der korrekten Aussprache des Korans?", ["Tajwid", "Tafsir", "Fiqh", "Sira"], "Der Tajwid lehrt, jeden Buchstaben von seinem Artikulationsort aus mit seinen Eigenschaften auszusprechen."),
"quran_078": ("Wie nennt man eine Person, die den ganzen Koran auswendig gelernt hat?", ["Einen Hafiz", "Einen Imam", "Einen Muezzin", "Einen Mufti"], "Hafiz bedeutet „der Bewahrende“: Er trägt den gesamten Koran in seinem Gedächtnis."),
"quran_079": ("Wie nennt man das geschriebene Exemplar des Korans?", ["Einen Mushaf", "Einen Hadith", "Einen Juz'", "Einen Minbar"], "Der Mushaf ist der zwischen zwei Buchdeckeln gesammelte Koran; ein Juz' ist einer seiner dreißig Teile."),
"quran_080": ("In welcher Sure erscheint die Basmala zweimal?", ["An-Naml", "Al-Fatiha", "At-Tawba", "Al-Baqara"], "Neben ihrer Eröffnung zitiert An-Naml die Basmala am Anfang von Sulaymans Brief an die Königin von Saba (27:30)."),
}
